def edge_metrics(p,y,ij,mask):
 pairs=ij[mask];d=p[pairs[:,1]]-p[pairs[:,0]];r=y[pairs[:,1]]-y[pairs[:,0]];err=abs(d-r)
 if len(d)==0:return dict(pair_count=0,mean_pred_jump_MPa=None,mean_ref_jump_MPa=None,signed_excess_MPa=None,mean_jump_error_MPa=None,Q95_jump_error_MPa=None,max_jump_error_MPa=None)
 return dict(pair_count=len(d),mean_pred_jump_MPa=float(abs(d).mean()),mean_ref_jump_MPa=float(abs(r).mean()),signed_excess_MPa=float((abs(d)-abs(r)).mean()),mean_jump_error_MPa=float(err.mean()),Q95_jump_error_MPa=float(np.quantile(err,.95)),max_jump_error_MPa=float(err.max()))

