  # Geometry-only ridge at maximum absolute normal-X in each original Y row.
  uY=np.unique(xyz[:,1]);ridge=np.array([xyz[np.flatnonzero(xyz[:,1]==yy)[np.argmax(abs(normal[xyz[:,1]==yy,0]))],0] for yy in uY]);ridgeX=ridge[np.abs(mid[:,1,None]-uY[None,:]).argmin(1)];f=np.c_[f,abs(mid[:,0]-ridgeX)];ci=np.flatnonzero(cross);ii=np.flatnonzero(inside);scale=np.maximum(np.std(f[ii],axis=0),1e-9);control=ii[cKDTree(f[ii]/scale).query(f[ci]/scale)[1]];refdelta=abs(y[ij[:,1]]-y[ij[:,0]]);f2=np.c_[f/scale,refdelta/max(np.std(refdelta[ii]),1e-9)];post=ii[cKDTree(f2[ii]).query(f2[ci])[1]]
  np.savez_compressed(R/'12_tile_boundary_analysis'/(sid+'_MATCHES.npz'),boundary_edge_indices=ci,geometry_interior_indices=control,reference_gradient_posthoc_indices=post,feature_matrix=f,feature_scale=scale)
  originalbounds=np.unique(mid[cross,0]);pointdist=np.min(abs(xyz[:,0,None]-originalbounds[None,:]),axis=1);edgedist=np.min(abs(mid[:,0,None]-originalbounds[None,:]),axis=1)
